// E-Ticaret Sistemi - Ana Giriş Noktası
// Main Entry Point

// Modelleri içe aktar
"src/models/user.hudhud" utiliser;
"src/models/product.hudhud" utiliser;
"src/models/order.hudhud" utiliser;

// Servisleri içe aktar
"src/services/auth.hudhud" utiliser;
"src/services/payment.hudhud" utiliser;
"src/services/notification.hudhud" utiliser;

// Yardımcı classeları içe aktar
"src/utils/validation.hudhud" utiliser;
"src/utils/formatting.hudhud" utiliser;

imprimer("============================================================");
imprimer("E-Ticaret Sistemi - Modüler Mimari Demo");
imprimer("============================================================\n");

// Servis örnekleri oluştur
var authService = nouveau AuthService();
var paymentService = nouveau PaymentService();
var notificationService = nouveau NotificationService();

imprimer("1️⃣  KULLANICI KAYDI");
imprimer("─────────────────────────────────────────────────────────\n");

// Yeni utiliserıcı oluştur
var newUser = nouveau User("Davut Süleyman", "davut@example.com", "güvenli123");
imprimer("Kullanıcı oluşturuldu: " + newUser.bilgi());

// Email vraila
si (Validation.email(newUser.email)) {
    imprimer("✓ Email geçerli: " + newUser.email);
} sinon {
    imprimer("✗ Email geçersiz");
}

// Kullanıcıyı kaydet
var authResult = authService.register(newUser);
si (authResult.success) {
    imprimer("✓ " + authResult.message + " (ID: " + authResult.userId + ")");

    // Hoş geldin bildirimi
    notificationService.send(
        newUser.email,
        "Hoş Geldiniz!",
        "Aramıza hoş geldiniz, " + newUser.name
    );
}

imprimer("\n2️⃣  ÜRÜN OLUŞTURMA");
imprimer("─────────────────────────────────────────────────────────\n");

// Ürün oluştur
var product = nouveau Product("MacBook Pro M3", 45000, 10, "Elektronik");
imprimer("Ürün oluşturuldu: " + product.bilgi());

// Fiyat vraila
si (Validation.price(product.price)) {
    imprimer("✓ Fiyat geçerli: " + Formatting.currency(product.price, "TRY"));
}

// Stok kontrolü
si (product.inStock()) {
    imprimer("✓ Ürün stokta mevcut");
} sinon {
    imprimer("✗ Ürün stokta yok");
}

imprimer("\n3️⃣  SİPARİŞ OLUŞTURMA");
imprimer("─────────────────────────────────────────────────────────\n");

// Sipariş oluştur
var order = nouveau Order(
    newUser.id,
    product.id,
    1,
    product.price
);
imprimer("Sipariş oluşturuldu: " + order.bilgi());

imprimer("\n4️⃣  ÖDEME İŞLEMİ");
imprimer("─────────────────────────────────────────────────────────\n");

// Ödeme işle
var paymentResult = paymentService.process(
    order.id,
    order.totalPrice,
    "credit_card"
);

si (paymentResult.success) {
    imprimer("✓ " + paymentResult.message);
    imprimer("  İşlem No: " + paymentResult.transactionId);
    imprimer("  Tutar: " + Formatting.currency(paymentResult.amount, "TRY"));
    imprimer("  Yöntem: " + paymentResult.method);

    // Siparişi onayla
    order.confirm();
    imprimer("✓ Sipariş onaylandı: " + order.status);

    // Sipariş onay bildirimi
    notificationService.send(
        newUser.email,
        "Siparişiniz Onaylandı",
        "Sipariş numaranız: " + order.id + " - Toplam: " + Formatting.currency(order.totalPrice, "TRY")
    );
} sinon {
    imprimer("✗ Ödeme başarısız: " + paymentResult.error);
}

imprimer("\n============================================================");
imprimer("✓ E-Ticaret sistemi demo tamamlandı!");
imprimer("✓ Modüler, ölçeklenebilir ve bakımı kolay mimari");
imprimer("============================================================");

