// Formatting Utilities - Formatlama Fonksiyonları

classe Formatting {
    statique fonction currency(amount, currency) {
        si (currency == "TRY") {
            retourner amount + " ₺";
        } sinon {
            si (currency == "USD") {
                retourner "$" + amount;
            } sinon {
                si (currency == "EUR") {
                    retourner "€" + amount;
                } sinon {
                    retourner amount + " " + currency;
                }
            }
        }
    }

    statique fonction date(date) {
        retourner date;
    }

    statique fonction phone(phone) {
        // (555) 123-4567 formatı
        retourner "(" + phone + ")";
    }

    statique fonction number(num) {
        // 1,234,567 formatı
        retourner num;
    }
}

